#!/usr/bin/env python
import os
import sys
import django

# Setup Django environment
sys.path.append('/workspace')
os.environ.setdefault('DJANGO_SETTINGS_MODULE', 'map_memories.settings')
django.setup()

from shop.models import ShopItem
from accounts.models import User
from shop.models import UserItem

# Base64 images provided by user
images = [
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,",
    "data:image/png;base64,"
]

# Shop items data
shop_items_data = [
    {
        'name': 'Magical Marker',
        'description': 'A powerful marker with mystical properties that enhances your map experience.',
        'price': 250,
        'stock': 100,
        'item_type': 'marker',
        'image_base64': images[0],
        'is_active': True,
        'is_available': True,
    },
    {
        'name': 'Explorer Theme',
        'description': 'Transform your map with this beautiful explorer theme.',
        'price': 500,
        'stock': 50,
        'item_type': 'theme',
        'image_base64': images[1], 
        'is_active': True,
        'is_available': True,
    },
    {
        'name': 'Memory Enhancer',
        'description': 'Special tool to enhance and organize your memories.',
        'price': 300,
        'stock': 75,
        'item_type': 'tool',
        'image_base64': images[2],
        'is_active': True,
        'is_available': True,
    },
    {
        'name': 'Location Tracker',
        'description': 'Advanced location tracking device for precise mapping.',
        'price': 400,
        'stock': 25,
        'item_type': 'tracker',
        'image_base64': images[3],
        'is_active': True,
        'is_available': True,
    }
]

print("Starting shop items seeding...")

# Clear existing shop items if needed
existing_count = ShopItem.objects.count()
if existing_count > 0:
    print(f"Found {existing_count} existing shop items. Clearing...")
    ShopItem.objects.all().delete()

# Create new shop items
created_items = []
for item_data in shop_items_data:
    item = ShopItem.objects.create(**item_data)
    created_items.append(item)
    print(f"Created shop item: {item.name} (ID: {item.id})")

# Gift items to admin user
try:
    admin_user = User.objects.filter(role='admin').first()
    if admin_user:
        print(f"Found admin user: {admin_user.username}")
        
        # Gift each item to admin
        for item in created_items:
            user_item, created = UserItem.objects.get_or_create(
                user=admin_user,
                shop_item=item,
                defaults={'quantity': 1}
            )
            if created:
                print(f"Gifted {item.name} to admin user {admin_user.username}")
            else:
                user_item.quantity += 1
                user_item.save()
                print(f"Added 1 more {item.name} to admin user {admin_user.username} (total: {user_item.quantity})")
    else:
        print("No admin user found. Items created but not gifted.")
        
except Exception as e:
    print(f"Error gifting items to admin: {e}")

print(f"✅ Successfully seeded {len(created_items)} shop items!")
